using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.SupplierPayments;public class CreateModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty(SupportsGet=true)]public Guid? SupplierId{get;set;}[BindProperty]public SupplierPaymentForm Item{get;set;}=new();public SelectList Suppliers{get;private set;}=null!;public SelectList Methods{get;private set;}=null!;public IReadOnlyList<PolicyOption> Policies{get;private set;}=[];public async Task<IActionResult> OnGetAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Add))return Forbid();if(SupplierId.HasValue)Item.SupplierId=SupplierId.Value;await Load();return Page();}public async Task<IActionResult> OnPostAsync(){SupplierId=Item.SupplierId;if(!await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Add))return Forbid();if(ModelState.IsValid)try{await transactions.CreateSupplierPaymentAsync(new(Item.SupplierId,Item.SupplierReceiptId,Item.Date,Item.Amount,Item.PaymentMethodId,Item.Comments));TempData["Message"]="تم تسجيل الدفع للمورد";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}await Load();return Page();}private async Task Load(){Suppliers=new(await db.Suppliers.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name",SupplierId);Methods=new(await db.PaymentMethods.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");if(SupplierId.HasValue)Policies=await transactions.GetSupplierPoliciesAsync(SupplierId.Value);}}
